import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";

function BarberDashboard() {
	const navigate = useNavigate();
	const [barber, setBarber] = useState(null);
	const [activeTab, setActiveTab] = useState("profile");

	useEffect(() => {
		const barberData = localStorage.getItem("barber");
		if (barberData) {
			setBarber(JSON.parse(barberData));
		} else {
			navigate("/barber/login");
		}
	}, [navigate]);

	const handleLogout = () => {
		localStorage.removeItem("token");
		localStorage.removeItem("barber");
		navigate("/");
	};

	if (!barber) {
		return <div>Loading...</div>;
	}

	return (
		<div className="max-w-6xl mx-auto">
			{/* Header */}
			<div className="bg-white rounded-lg shadow-md p-6 mb-6">
				<div className="flex justify-between items-center mb-4">
					<h1 className="text-3xl font-bold text-gray-800">
						Welcome, {barber.name}!
					</h1>
					<button
						onClick={handleLogout}
						className="bg-red-600 text-white px-4 py-2 rounded hover:bg-red-700"
					>
						Logout
					</button>
				</div>

				<div className="grid md:grid-cols-3 gap-6">
					<div className="bg-blue-50 p-4 rounded-lg">
						<h3 className="text-lg font-semibold text-blue-800 mb-2">
							Business Info
						</h3>
						<p>
							<strong>Business:</strong> {barber.businessName}
						</p>
						<p>
							<strong>Location:</strong> {barber.location}
						</p>
						<p>
							<strong>Email:</strong> {barber.email}
						</p>
					</div>

					<div className="bg-green-50 p-4 rounded-lg">
						<h3 className="text-lg font-semibold text-green-800 mb-2">
							Specialties
						</h3>
						<div className="flex flex-wrap gap-2">
							{barber.specialties.map((specialty, index) => (
								<span
									key={index}
									className="bg-green-200 text-green-800 px-2 py-1 rounded text-sm"
								>
									{specialty}
								</span>
							))}
						</div>
					</div>

					<div className="bg-purple-50 p-4 rounded-lg">
						<h3 className="text-lg font-semibold text-purple-800 mb-2">
							Quick Actions
						</h3>
						<button className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700 w-full mb-2">
							View Appointments
						</button>
						<button className="bg-green-600 text-white px-4 py-2 rounded hover:bg-green-700 w-full mb-2">
							Update Profile
						</button>
						<button className="bg-purple-600 text-white px-4 py-2 rounded hover:bg-purple-700 w-full">
							Set Availability
						</button>
					</div>
				</div>
			</div>

			<div className="bg-white rounded-lg shadow-md p-6">
				<div className="border-b border-gray-200 mb-6">
					<nav className="-mb-px flex space-x-8">
						<button
							onClick={() => setActiveTab("profile")}
							className={`py-2 px-1 border-b-2 font-medium text-sm ${
								activeTab === "profile"
									? "border-blue-500 text-blue-600"
									: "border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300"
							}`}
						>
							Profile
						</button>
						<button
							onClick={() => setActiveTab("appointments")}
							className={`py-2 px-1 border-b-2 font-medium text-sm ${
								activeTab === "appointments"
									? "border-blue-500 text-blue-600"
									: "border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300"
							}`}
						>
							Appointments
						</button>
						<button
							onClick={() => setActiveTab("availability")}
							className={`py-2 px-1 border-b-2 font-medium text-sm ${
								activeTab === "availability"
									? "border-blue-500 text-blue-600"
									: "border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300"
							}`}
						>
							Availability
						</button>
					</nav>
				</div>

				<div className="min-h-64">
					{activeTab === "profile" && (
						<div>
							<h3 className="text-lg font-semibold text-gray-800 mb-4">
								Profile Information
							</h3>
							<div className="grid md:grid-cols-2 gap-4">
								<div>
									<label className="block text-sm font-medium text-gray-700 mb-1">
										Name
									</label>
									<input
										type="text"
										value={barber.name}
										className="w-full px-3 py-2 border border-gray-300 rounded focus:outline-none focus:border-blue-500"
										readOnly
									/>
								</div>
								<div>
									<label className="block text-sm font-medium text-gray-700 mb-1">
										Business Name
									</label>
									<input
										type="text"
										value={barber.businessName}
										className="w-full px-3 py-2 border border-gray-300 rounded focus:outline-none focus:border-blue-500"
										readOnly
									/>
								</div>
								<div>
									<label className="block text-sm font-medium text-gray-700 mb-1">
										Location
									</label>
									<input
										type="text"
										value={barber.location}
										className="w-full px-3 py-2 border border-gray-300 rounded focus:outline-none focus:border-blue-500"
										readOnly
									/>
								</div>
								<div>
									<label className="block text-sm font-medium text-gray-700 mb-1">
										Email
									</label>
									<input
										type="text"
										value={barber.email}
										className="w-full px-3 py-2 border border-gray-300 rounded focus:outline-none focus:border-blue-500"
										readOnly
									/>
								</div>
							</div>
						</div>
					)}

					{activeTab === "appointments" && (
						<div>
							<h3 className="text-lg font-semibold text-gray-800 mb-4">
								Appointments
							</h3>
							<p className="text-gray-600">
								No appointments yet. When users start booking, they'll appear
								here.
							</p>
						</div>
					)}

					{activeTab === "availability" && (
						<div>
							<h3 className="text-lg font-semibold text-gray-800 mb-4">
								Availability
							</h3>
							<p className="text-gray-600">
								Set your working hours and availability here.
							</p>
						</div>
					)}
				</div>
			</div>
		</div>
	);
}

export default BarberDashboard;
